INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'The three PRIMARY motions of weaving (shedding, picking, beating-up) are called ''primary'' specifically because:', '["They are the newest inventions in loom technology","Without all three happening in the correct sequence for every single pick, no woven fabric can form at all — they are the fundamental, non-optional actions of interlacing","They only apply to shuttleless looms","They control only the fabric''s final color"]'::jsonb, 'Without all three happening in the correct sequence for every single pick, no woven fabric can form at all — they are the fundamental, non-optional actions of interlacing', 'Shedding (separating warp into two layers), picking (inserting weft through the shed), and beating-up (pushing the new pick to the fell of the cloth) must occur, in that order, for every single weft insertion — no other combination of loom motions can substitute for this core cycle, which is why they''re termed ''primary.''', 1, '{"primary-motions"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', '''Let-off'' and ''take-up'' are classified as secondary motions of weaving. Their essential role is to:', '["Insert the weft yarn into the shed","Continuously supply warp yarn from the beam at a controlled rate (let-off) and wind the newly formed fabric away at a controlled rate (take-up), maintaining correct warp tension and pick density throughout weaving","Stop the loom when a yarn breaks","Create the shed opening"]'::jsonb, 'Continuously supply warp yarn from the beam at a controlled rate (let-off) and wind the newly formed fabric away at a controlled rate (take-up), maintaining correct warp tension and pick density throughout weaving', 'Let-off releases warp from the warp beam as weaving consumes it, while take-up winds the finished fabric forward at a rate that sets the target picks-per-inch (PPI) — both must be precisely synchronized with the primary motions to maintain consistent warp tension and fabric density.', 2, '{"let-off","take-up"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Warp and weft stop motions (tertiary motions) exist mainly to:', '["Increase the loom''s maximum running speed","Automatically stop the loom immediately when a warp or weft yarn breaks, preventing a defect (like a missing end or float) from continuing to be woven into meters of fabric before a human notices","Insert extra color into the fabric","Control the fabric''s final width"]'::jsonb, 'Automatically stop the loom immediately when a warp or weft yarn breaks, preventing a defect (like a missing end or float) from continuing to be woven into meters of fabric before a human notices', 'Without stop motions, a single broken warp end or exhausted weft could continue being ''woven'' as a visible fault for a significant length of fabric before a human operator caught it; automatic sensing and immediate stopping minimizes the length of defective fabric produced per incident.', 2, '{"stop-motions"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'Warp sizing (applying a protective starch/PVA film to warp yarns before weaving) is essential mainly because warp yarns:', '["Need to be colored before weaving","Undergo far more repetitive abrasion and tension stress (against healds, reed, and each other) during weaving than weft yarns, so sizing adds protective strength and reduces hairiness/breakage","Are always synthetic and weft is always natural fiber","Never need any preparation before weaving"]'::jsonb, 'Undergo far more repetitive abrasion and tension stress (against healds, reed, and each other) during weaving than weft yarns, so sizing adds protective strength and reduces hairiness/breakage', 'Warp yarns are subjected to constant tension and repeated rubbing against heald eyes, reed dents, and adjacent warp threads throughout the entire weaving process (unlike weft, inserted once per pick); sizing coats the yarn with a protective film that increases smoothness and abrasion resistance, directly reducing warp breakage rates.', 1, '{"sizing"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A mill under-sizes its warp yarn (applies too little size add-on%) to cut chemical cost. What is the most likely direct consequence on the loom?', '["No consequence — sizing level has no effect on weaving performance","Increased warp breakage rate due to insufficient protection against abrasion, leading to more loom stoppages and lower weaving efficiency","The fabric automatically becomes wider","Weft insertion becomes faster"]'::jsonb, 'Increased warp breakage rate due to insufficient protection against abrasion, leading to more loom stoppages and lower weaving efficiency', 'Size add-on percentage is a carefully engineered tradeoff — too little size leaves warp yarn under-protected against the mechanical stresses of weaving, directly raising the warp break rate and the resulting stop-motion-triggered loom stoppages, hurting overall weaving efficiency despite the chemical cost saving.', 2, '{"sizing","efficiency"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', '''Drawing-in'' (threading each warp end individually through its heald eye and reed dent according to the weave design) is a preparatory step that must be redone for every new warp beam mainly because:', '["It can be reused indefinitely across any style with no changes","The specific threading order/pattern directly determines the weave structure and design (e.g., plain, twill, dobby pattern), so a new fabric design or repaired/replaced beam requires re-threading to match its intended structure","Drawing-in only affects the fabric''s color, not structure","It is purely a cosmetic step with no functional purpose"]'::jsonb, 'The specific threading order/pattern directly determines the weave structure and design (e.g., plain, twill, dobby pattern), so a new fabric design or repaired/replaced beam requires re-threading to match its intended structure', 'The order in which warp ends are threaded through healds (and which heald frame/shaft each end goes to) directly encodes the weave pattern — changing the fabric design requires re-drawing-in to the new threading plan, while an identical repeat style can sometimes use ''tying-in'' instead to save time.', 3, '{"drawing-in"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', '''Tying-in'' (knotting new warp ends to the tail ends of a depleted beam, matching each position) is preferred over full drawing-in when:', '["A completely new, different weave design is being started","The new warp is an identical repeat of the same fabric style/design as the previous beam, so matching yarn-to-yarn tying saves significant time versus re-threading every heald and dent from scratch","The loom type is being changed to a completely different technology","The mill wants to intentionally change the fabric''s structure"]'::jsonb, 'The new warp is an identical repeat of the same fabric style/design as the previous beam, so matching yarn-to-yarn tying saves significant time versus re-threading every heald and dent from scratch', 'Tying-in uses a knotting machine to join each new warp end to the corresponding old end still threaded in its heald/dent position — this only works correctly if the new warp uses the identical threading plan (same style), making it a major time-saver over full re-drawing-in for repeat orders.', 2, '{"tying-in"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'Rapier weaving machines insert weft using rigid or flexible rapier bands that carry the yarn across the shed. Compared to shuttle looms, their main advantage is:', '["They cannot handle any yarn type except cotton","Much higher weft insertion speed and the ability to insert different colored wefts easily (multi-color capability) without the noise/limitations of a flying shuttle","They require no weft yarn at all","They can only weave plain weave fabric"]'::jsonb, 'Much higher weft insertion speed and the ability to insert different colored wefts easily (multi-color capability) without the noise/limitations of a flying shuttle', 'Rapier looms replaced the flying shuttle with mechanically controlled rapier grippers that positively carry the weft across, enabling higher speeds, lower noise, and easy multi-color weft selection — a major productivity and versatility advance over traditional shuttle weaving.', 1, '{"rapier-loom"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Air-jet weaving machines use compressed air pulses (via main and relay nozzles) to propel the weft yarn across the shed. Their main LIMITATION compared to rapier or projectile looms is:', '["They are the slowest weft insertion method available","Loom width is somewhat more constrained by air propulsion consistency across the shed width, and they consume significant compressed air energy, making them best suited to narrower/medium width, high-speed fabric production","They cannot achieve high production speeds at all","They can only weave using metal wire, not textile yarn"]'::jsonb, 'Loom width is somewhat more constrained by air propulsion consistency across the shed width, and they consume significant compressed air energy, making them best suited to narrower/medium width, high-speed fabric production', 'Air-jet is actually the fastest common weft insertion technology for its suitable width range, but maintaining consistent air propulsion (with relay nozzle timing) across very wide looms is more technically challenging, and compressed air generation is energy-intensive — so air-jet dominates high-speed, moderate-width production rather than very wide fabrics.', 3, '{"air-jet-loom"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Water-jet weaving machines use a jet of water to propel weft yarn and are the fastest insertion method for certain applications, but they have one major fiber-compatibility limitation:', '["They work equally well on all fiber types with no restriction","They are essentially limited to hydrophobic (water-resistant) yarns like polyester and nylon filament, since water would damage or stain absorbent fibers like cotton","They can only be used with wool","They cannot weave any synthetic fiber at all"]'::jsonb, 'They are essentially limited to hydrophobic (water-resistant) yarns like polyester and nylon filament, since water would damage or stain absorbent fibers like cotton', 'Because the weft is propelled by an actual water jet, water-jet looms are restricted to fibers that won''t absorb/stain/swell from water contact — this makes them ideal for synthetic filament fabrics (like polyester linings) but unusable for absorbent natural fibers like cotton.', 2, '{"water-jet-loom"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Projectile weaving machines (e.g., Sulzer-type) carry weft yarn across the shed using small, independent gripper projectiles that are mechanically shot across and then returned. Their key advantage over rapier looms for VERY WIDE fabric is:', '["They cannot weave wide fabric at all","The projectile carries only the weft (not a full-width rapier band), reducing the mass/mechanism that must move across very wide looms, making them well-suited to extra-wide fabric like bedsheets/industrial fabric","They use no mechanical parts whatsoever","They only work with natural fiber yarns"]'::jsonb, 'The projectile carries only the weft (not a full-width rapier band), reducing the mass/mechanism that must move across very wide looms, making them well-suited to extra-wide fabric like bedsheets/industrial fabric', 'Unlike rapier systems that need a full-width rigid/flexible band reaching across the entire loom width, projectile looms use small individual grippers that detach and fly across, then are mechanically returned — this scales more efficiently to very wide fabric widths, which is why projectile technology historically dominated wide-width applications like sheeting.', 3, '{"projectile-loom"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A mill weaving plain, high-volume cotton shirting in a single or few colors would generally choose which weft insertion technology for the best cost-speed balance?', '["Water-jet, regardless of fiber type","Air-jet, since it offers very high insertion speed and is well suited to natural fiber high-volume, limited-color production","Only hand-shuttle looms for authenticity","Only projectile looms regardless of order type"]'::jsonb, 'Air-jet, since it offers very high insertion speed and is well suited to natural fiber high-volume, limited-color production', 'Air-jet looms are the standard high-speed workhorse for high-volume cotton fabric production (like shirting) where color changes are infrequent — they combine excellent speed with good compatibility for natural fiber yarns, unlike water-jet (synthetic-only) or projectile (better suited to extra-wide/technical fabric).', 2, '{"loom-selection"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', '''Reed count'' (e.g., expressed in reeds per inch or a dent-count system) primarily determines:', '["The fabric''s final color","The maximum number of warp ends that can be accommodated per unit width, directly influencing warp density (EPI) and, combined with denting plan, fabric width and cover","The loom''s weft insertion speed","The type of fiber that can be woven"]'::jsonb, 'The maximum number of warp ends that can be accommodated per unit width, directly influencing warp density (EPI) and, combined with denting plan, fabric width and cover', 'The reed is a comb-like device whose dent spacing sets how many warp ends pass through each unit width; reed count (dents per inch) combined with how many ends are drawn per dent directly determines achievable warp density (EPI/ends-per-inch) and fabric cover.', 2, '{"reed"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'The reed also performs a critical PRIMARY-motion-adjacent function during beating-up. What is it?', '["It dyes the yarn as it passes","It pushes (beats) each newly inserted weft pick firmly up to the fell of the cloth, setting the pick spacing (PPI) and fabric firmness","It measures the fabric''s final GSM","It cuts the warp yarn at the end of weaving"]'::jsonb, 'It pushes (beats) each newly inserted weft pick firmly up to the fell of the cloth, setting the pick spacing (PPI) and fabric firmness', 'Beyond spacing/guiding warp ends, the reed is mounted on the sley/batten and physically swings forward each cycle to beat the just-inserted weft pick tightly against the previously woven fabric — this beating action is what actually sets picks-per-inch (PPI) and overall fabric compactness.', 2, '{"reed","beating-up"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A ''temple'' (or ''tenter'') device mounted near the fell of the cloth on a loom exists to:', '["Insert extra weft picks for pattern effects","Hold the fabric at its correct, full weaving width during weaving, preventing the natural tendency of fabric to narrow/draw in from weft tension, which would otherwise cause edge defects","Measure the exact loom speed","Apply dye to the fabric edges"]'::jsonb, 'Hold the fabric at its correct, full weaving width during weaving, preventing the natural tendency of fabric to narrow/draw in from weft tension, which would otherwise cause edge defects', 'As weft is beaten in under tension, fabric naturally tends to contract inward from its intended width (weft take-up/draw-in); temples use pins or rollers gripping the fabric edges to hold the correct width, preventing selvedge distortion, edge cracks, or non-uniform width along the fabric''s length.', 2, '{"temple"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'If a loom''s temple malfunctions or is set incorrectly during weaving, the most likely visible fabric defect is:', '["A uniform color change across the whole fabric","Excessive width narrowing (draw-in) near the selvedges, sometimes causing selvedge cracks or an uneven, wavy fabric edge","The complete absence of any weft yarn","A change in the fiber type being woven"]'::jsonb, 'Excessive width narrowing (draw-in) near the selvedges, sometimes causing selvedge cracks or an uneven, wavy fabric edge', 'Without proper temple function holding the fabric edges at full width, the natural contraction from weft insertion tension goes uncontrolled, producing narrowed, wavy, or cracked selvedges — a classic, directly traceable weaving defect.', 3, '{"temple","defects"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Dobby looms can weave more complex, small-repeat patterns (like small geometric motifs) beyond plain weave/simple twills, compared to a basic cam/tappet shedding mechanism, mainly because:', '["Dobby mechanisms can only weave plain weave, same as tappet looms","A dobby mechanism independently controls a larger number of heald shafts (frames) with individually programmable lifting sequences, allowing more complex, varied weave patterns than the limited number of shafts a simple tappet/cam mechanism practically supports","Dobby looms use no healds at all","Dobby looms are limited to only 2 colors"]'::jsonb, 'A dobby mechanism independently controls a larger number of heald shafts (frames) with individually programmable lifting sequences, allowing more complex, varied weave patterns than the limited number of shafts a simple tappet/cam mechanism practically supports', 'Tappet/cam shedding mechanisms are mechanically limited to a small number of shafts with fixed, simple lifting patterns (good for plain weave/basic twills); dobby mechanisms can control many more shafts with programmable, more varied lifting sequences, enabling more complex small-to-medium repeat patterns like birds-eye, small dobby motifs, and complex twills.', 3, '{"dobby-loom"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Jacquard looms take pattern capability even further than dobby looms because they control:', '["Only 2 heald shafts, fewer than a dobby loom","Each individual warp end independently (rather than groups of ends sharing a shaft), enabling large-scale, intricate, non-repeating or very large-repeat designs like complex florals and figured brocades","Only the weft insertion speed, not warp lifting","The fabric''s finishing process, not its weaving"]'::jsonb, 'Each individual warp end independently (rather than groups of ends sharing a shaft), enabling large-scale, intricate, non-repeating or very large-repeat designs like complex florals and figured brocades', 'Unlike dobby (groups of ends per shaft), jacquard mechanisms control every single warp end''s up/down position independently via individually programmed hooks/harness cords — this is what enables extremely intricate, large-scale figured designs (brocade, complex florals) impossible on shaft-based dobby or tappet systems.', 3, '{"jacquard-loom"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A ''float'' defect in woven fabric refers to:', '["A pick or end that correctly interlaces according to the intended weave pattern","A warp or weft yarn segment that unintentionally skips over/under more adjacent threads than the design calls for, usually from a threading or shedding error, creating a visible loose, unsecured segment","The correct appearance of a satin weave''s intentional long floats","A fabric that has been dyed unevenly"]'::jsonb, 'A warp or weft yarn segment that unintentionally skips over/under more adjacent threads than the design calls for, usually from a threading or shedding error, creating a visible loose, unsecured segment', 'While SOME weave structures (like satin) intentionally include long floats as part of the design, a ''float defect'' specifically refers to an UNINTENDED extra-long float caused by a drawing-in error, broken heald, or shedding malfunction — it''s a fault precisely because it deviates from the intended structure, not because floats are inherently bad.', 2, '{"float-defect"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', '''Reed marks'' (visible fine lines running lengthwise in woven fabric, aligned with warp direction) are typically caused by:', '["Incorrect weft yarn color","Uneven distribution of warp ends across reed dents (e.g., wrong denting plan or damaged reed dents), causing visible density streaks running the length of the fabric","The fabric being cut incorrectly after weaving","A problem with the take-up motion only"]'::jsonb, 'Uneven distribution of warp ends across reed dents (e.g., wrong denting plan or damaged reed dents), causing visible density streaks running the length of the fabric', 'Reed marks appear as fine lengthwise streaks when warp ends aren''t evenly distributed through the reed dents (whether from an incorrect denting plan, a bent/damaged dent, or uneven drawing-in) — since this pattern repeats down the entire fabric length, it shows as a persistent lengthwise line defect.', 3, '{"reed-marks","defects"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', '''Starting mark'' (a visible line defect where a loom restarts weaving after a stoppage) is typically caused by:', '["The natural weave pattern of twill fabric","A change in warp tension and/or beating force right at the restart point, since the fabric was stationary during the stop while the machine''s dynamic tension settings were optimized for continuous running","A dye batch change","Correct temple function"]'::jsonb, 'A change in warp tension and/or beating force right at the restart point, since the fabric was stationary during the stop while the machine''s dynamic tension settings were optimized for continuous running', 'During a stoppage, static warp tension differs from the dynamic tension during running, and the first few picks after restart can be beaten with slightly different force/spacing than steady-state weaving — this creates a faint but often visible line at every restart point, a classic loom-efficiency-linked quality issue (frequent stops = more starting marks).', 3, '{"starting-mark","defects"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'Loom efficiency (%) is calculated by comparing actual fabric production against theoretical maximum production (based on loom RPM and running time). A mill with frequent warp breaks will show:', '["Higher efficiency than a mill with fewer breaks, all else equal","Lower efficiency, since each break causes downtime for the stop-motion-triggered stoppage and manual repair, directly reducing actual output versus the theoretical maximum","No change in efficiency regardless of break frequency","Efficiency is unrelated to any stoppage cause"]'::jsonb, 'Lower efficiency, since each break causes downtime for the stop-motion-triggered stoppage and manual repair, directly reducing actual output versus the theoretical maximum', 'Loom efficiency directly reflects the ratio of actual running time to total available time; every warp/weft break triggers a stop-motion halt and requires manual repair time, so higher break frequency directly translates to lower efficiency, making break-rate reduction a key weaving productivity lever.', 1, '{"loom-efficiency"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Comparing two identical looms weaving the same fabric style, Loom A runs at 600 RPM with 2% efficiency loss from stoppages, Loom B runs at 500 RPM with negligible stoppages. Which loom likely produces MORE actual fabric per shift?', '["Always Loom A, since higher RPM always wins regardless of efficiency","It depends on the actual numbers — the answer requires comparing (RPM × efficiency%) for each, since a faster but less efficient loom can still out- or under-produce a slower, more efficient one depending on the specific efficiency gap","Always Loom B, since fewer stoppages always wins regardless of RPM","Both must always produce identical output by definition"]'::jsonb, 'It depends on the actual numbers — the answer requires comparing (RPM × efficiency%) for each, since a faster but less efficient loom can still out- or under-produce a slower, more efficient one depending on the specific efficiency gap', 'Actual production is proportional to nominal speed multiplied by efficiency%, not raw RPM alone — a mill floor manager must calculate effective output (RPM × efficiency) for a fair comparison rather than assuming the higher-RPM machine automatically wins; this is a common real-world trap when comparing loom performance.', 3, '{"loom-efficiency","production-calc"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Fabric ''cover factor'' (a measure of how much of the fabric''s area is covered by yarn versus open space) is influenced by which combination of factors?', '["Only the fabric''s final color","Yarn count (thickness) together with thread density (EPI/PPI) — finer yarn at the same density gives lower cover, while higher density at the same count gives higher cover","Only the loom''s brand and age","Only the weave structure''s name, unrelated to yarn or density"]'::jsonb, 'Yarn count (thickness) together with thread density (EPI/PPI) — finer yarn at the same density gives lower cover, while higher density at the same count gives higher cover', 'Cover factor mathematically combines yarn diameter (derived from count) and thread spacing (EPI/PPI) — since it measures the proportion of the fabric''s area actually covered by yarn, both variables directly determine it; two fabrics with the same EPI but different yarn counts will have measurably different cover factors.', 3, '{"cover-factor"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A woven fabric spec calls for a HIGH cover factor (e.g., for a downproof or windproof fabric). To achieve this while keeping the fabric as light (low GSM) as possible, a fabric engineer would prioritize:', '["Using the coarsest possible yarn at low density","Using finer, higher-count yarn at high thread density, since finer yarn achieves more coverage per unit weight than coarse yarn at the same density","Cover factor is unrelated to GSM or windproof performance","Reducing thread density as much as possible"]'::jsonb, 'Using finer, higher-count yarn at high thread density, since finer yarn achieves more coverage per unit weight than coarse yarn at the same density', 'Because cover factor depends on both yarn diameter and density, a fabric engineer targeting high cover at low weight uses fine, high-count yarn packed at high density — this achieves the tight weave structure needed for downproof/windproof performance without the excess weight that coarse yarn at high density would add.', 3, '{"cover-factor","fabric-engineering"}'::text[]);
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Twill weave fabric (e.g., denim, gabardine) is characterized by its distinctive diagonal line (wale) pattern. This diagonal appears because:', '["The weft yarn is dyed in a diagonal gradient","Each successive pick''s interlacing point shifts by one (or more) warp ends compared to the previous pick, creating a stepped, diagonal alignment of interlacing points across the fabric","The fabric is cut on the bias after weaving","Twill fabric has no structural difference from plain weave"]'::jsonb, 'Each successive pick''s interlacing point shifts by one (or more) warp ends compared to the previous pick, creating a stepped, diagonal alignment of interlacing points across the fabric', 'Twill''s diagonal wale is a direct structural consequence of the weave''s step pattern — each pick''s over/under interlacing sequence is offset by a defined number of ends from the previous pick, and this systematic offset, repeated pick after pick, visually creates the characteristic diagonal line.', 2, '{"twill-weave"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Compared to plain weave at the same yarn count and density, twill weave fabric generally has:', '["Identical drape, strength, and abrasion resistance in every respect","Fewer interlacing points per unit area (since floats span more than one thread), giving it generally better drape/flexibility and sometimes different abrasion characteristics than the tighter, more frequently-interlaced plain weave","Always lower tensile strength than plain weave regardless of construction","No difference in visual appearance at all"]'::jsonb, 'Fewer interlacing points per unit area (since floats span more than one thread), giving it generally better drape/flexibility and sometimes different abrasion characteristics than the tighter, more frequently-interlaced plain weave', 'Plain weave interlaces every single warp-weft crossing (maximum interlacing frequency), while twill''s floats span multiple threads before interlacing again — this structural difference typically gives twill better drape and a different surface/abrasion character compared to the tighter, more rigid plain weave structure at equivalent yarn/density.', 3, '{"twill-vs-plain"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Satin weave is defined by long floats and widely, irregularly spaced interlacing points (to avoid visible diagonal lines). This structure gives satin fabric its characteristic:', '["Very rough, matte surface with high friction","High luster/sheen and smooth surface, since the long floats let more of the yarn''s surface reflect light evenly, but also generally lower abrasion resistance due to fewer interlacing points holding the structure together","Maximum possible strength and abrasion resistance of any weave type","Complete absence of any diagonal or pattern effect intentionally, same as plain weave''s flat appearance goal"]'::jsonb, 'High luster/sheen and smooth surface, since the long floats let more of the yarn''s surface reflect light evenly, but also generally lower abrasion resistance due to fewer interlacing points holding the structure together', 'Satin''s long floats present a smooth, largely unbroken yarn surface to light, creating high luster — but this same feature (few interlacing points) means the structure is inherently less stable/durable under abrasion than plain or twill weave, a direct structure-property tradeoff.', 3, '{"satin-weave"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', '''Leno weave'' (used for lightweight, open, stable fabrics like mosquito netting or scrim) achieves structural stability at very open/low densities mainly through:', '["Extremely high thread density, same as any tightly woven fabric","A special crossing (figure-8 twisting) of adjacent warp ends around each weft pick, mechanically locking the weft in place and preventing yarn slippage even at very open, low-density construction","Chemical bonding between warp and weft after weaving","Using only synthetic fiber, never natural fiber"]'::jsonb, 'A special crossing (figure-8 twisting) of adjacent warp ends around each weft pick, mechanically locking the weft in place and preventing yarn slippage even at very open, low-density construction', 'Leno weave uses a doup/half-heald mechanism to physically twist pairs of warp ends around each other, trapping each weft pick between the twisted warp ends — this mechanical locking is what allows leno fabrics to remain stable and non-slipping even at extremely open, low-density constructions where plain weave would simply fall apart.', 3, '{"leno-weave"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Pile weave fabrics (e.g., corduroy, velvet, terry toweling) are structurally distinct from flat weaves because they include:', '["No warp yarn at all","An additional set of yarns (extra warp or weft) that form raised loops or cut tufts above the base (ground) fabric structure, creating a three-dimensional surface texture","Only a difference in dye color, not structure","A weave that is impossible to produce on any modern loom"]'::jsonb, 'An additional set of yarns (extra warp or weft) that form raised loops or cut tufts above the base (ground) fabric structure, creating a three-dimensional surface texture', 'Pile fabrics use a supplementary yarn system beyond the basic ground weave — these extra yarns are woven in such a way that they form raised loops (like terry toweling, left uncut) or are later cut to form a plush tufted surface (like velvet/corduroy) — giving pile fabrics their signature 3D surface texture unlike any flat weave.', 2, '{"pile-weave"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Terry toweling fabric''s absorbent loops are formed specifically through a controlled variation of which secondary motion?', '["Shedding motion, changed for every single pick","Take-up motion, which is deliberately varied (slack-tension weaving) in a repeating cycle to allow certain picks to push forward into loops instead of being beaten tightly to the fell","Picking motion speed only","Weft color change only"]'::jsonb, 'Take-up motion, which is deliberately varied (slack-tension weaving) in a repeating cycle to allow certain picks to push forward into loops instead of being beaten tightly to the fell', 'Terry weaving uses a special slack-tension let-off/take-up cycle: for most picks the fabric is held taut and beaten normally, but periodically the take-up is relaxed, allowing a group of picks to be pushed forward together into pile loops rather than beaten tight — this controlled take-up variation is the specific mechanism that creates terry''s absorbent loop pile.', 3, '{"terry-weave","pile"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Selvedge (the tightly woven, self-finished edge of a woven fabric) serves a functional purpose during weaving primarily by:', '["Adding decorative color only, with no functional role","Preventing the fabric edge from fraying/unraveling and providing a stable structure for the weft to turn back into on shuttle looms, or for shuttleless looms, containing the leno/tucked-in edge mechanism that secures cut weft ends","Determining the fabric''s final GSM","Controlling the loom''s weft insertion speed"]'::jsonb, 'Preventing the fabric edge from fraying/unraveling and providing a stable structure for the weft to turn back into on shuttle looms, or for shuttleless looms, containing the leno/tucked-in edge mechanism that secures cut weft ends', 'Selvedge is typically woven more tightly/densely than the fabric body specifically to stabilize the edge against fraying, and on shuttleless looms (where weft is cut at each edge rather than being one continuous thread as with a shuttle), a leno or tuck-in device is needed at the selvedge specifically to secure these cut weft ends in place.', 3, '{"selvedge"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Warp yarn breakage rates are generally expected to be HIGHER than weft yarn breakage rates on the same loom running the same fabric. The main reason is:', '["Warp yarn is always weaker than weft yarn by definition","Warp yarns are under continuous tension and repetitive abrasion (against healds/reed) for the ENTIRE weaving duration, while each weft yarn only experiences the stress of a single insertion pass per pick","Weft yarn experiences more total stress than warp yarn","There is no expected difference between warp and weft breakage rates"]'::jsonb, 'Warp yarns are under continuous tension and repetitive abrasion (against healds/reed) for the ENTIRE weaving duration, while each weft yarn only experiences the stress of a single insertion pass per pick', 'Every individual warp end stays under tension and repeatedly rubs against heald eyes and reed dents for the full length of fabric woven, while a given length of weft only passes through the shed once during its single insertion — this fundamentally different exposure to mechanical stress is why warp sizing exists and why warp breaks are generally the more critical efficiency concern.', 2, '{"warp-vs-weft","breakage"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A fabric technologist needs to increase a woven fabric''s tear strength without changing yarn count or fiber type. Which weave-related change is most likely to help?', '["Switching to a tighter plain weave with maximum interlacing","Switching to (or increasing the float length of) a twill or similar weave with fewer, longer floats, since fewer interlacing points per area generally allows yarns to move/group together under tear stress, distributing the load and improving tear strength","Tear strength cannot be affected by weave structure at all","Increasing the reed count while keeping everything else identical always reduces tear strength"]'::jsonb, 'Switching to (or increasing the float length of) a twill or similar weave with fewer, longer floats, since fewer interlacing points per area generally allows yarns to move/group together under tear stress, distributing the load and improving tear strength', 'Tear strength (resistance to a propagating tear) is generally improved when yarns can move/bunch together to share the tearing load — tighter, plain-weave structures with maximum interlacing restrict this yarn mobility, while looser-interlaced structures like twill allow yarns to group under stress, which is why twill/looser weaves often show better tear strength than an equally dense plain weave.', 3, '{"tear-strength","weave-structure"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', '''Denting plan'' refers to the specific rule for how many warp ends are drawn through each individual reed dent (e.g., 2 ends per dent). Changing the denting plan while keeping the same reed and same total ends will primarily affect:', '["Only the fabric''s color","The fabric''s finished width and the visual/structural distribution (grouping) of warp ends, which can also influence reed-mark risk","The type of fiber used","The loom''s picking speed"]'::jsonb, 'The fabric''s finished width and the visual/structural distribution (grouping) of warp ends, which can also influence reed-mark risk', 'With a fixed reed (fixed dent count per inch) and fixed total number of warp ends, changing ends-per-dent changes how many dents are actually used, which changes the resulting fabric width — and grouping multiple ends tightly per dent versus spreading them out can also create visible density variation (reed-mark risk) if not planned carefully.', 3, '{"denting-plan"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A weaving mill''s quality team finds that a specific defect (''missing pick'' — a weft row entirely absent) keeps recurring at regular intervals matching the weft yarn package''s typical yardage. What should they suspect first?', '["Random chance, with no investigatable pattern","A systematic weft-feeder or weft-break-detection issue occurring around package/cone changes (e.g., splicing failures or the weft break detector''s sensitivity at low-yarn-remaining conditions), since the recurrence interval matches package changeover frequency","The fabric''s dye recipe","The warp beam''s total length"]'::jsonb, 'A systematic weft-feeder or weft-break-detection issue occurring around package/cone changes (e.g., splicing failures or the weft break detector''s sensitivity at low-yarn-remaining conditions), since the recurrence interval matches package changeover frequency', 'When a defect recurs at an interval matching a specific process event (here, weft package changeover yardage), that''s a strong diagnostic clue pointing to that specific transition point (splice quality, feeder tension changes, or detector behavior near package end) rather than a random or unrelated cause — a classic root-cause-analysis pattern-matching approach.', 3, '{"troubleshooting","missing-pick"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Warp beam creel capacity and warping machine design (e.g., direct/beam warping vs. sectional warping) choice depends heavily on:', '["Only the final fabric''s color requirements","The complexity of the warp yarn pattern (e.g., single-color mass production vs. multi-colored striped/patterned warps) and total order volume, since sectional warping better handles complex multi-color patterns while direct warping is more efficient for simple, large-volume single-color warps","The loom''s weft insertion technology exclusively","Warping method has no effect on suitability for different fabric types"]'::jsonb, 'The complexity of the warp yarn pattern (e.g., single-color mass production vs. multi-colored striped/patterned warps) and total order volume, since sectional warping better handles complex multi-color patterns while direct warping is more efficient for simple, large-volume single-color warps', 'Direct (beam) warping efficiently produces large, simple, typically single-color warp beams for high-volume plain fabric; sectional warping builds the beam in narrow sections, allowing complex color patterns (stripes, checks) to be precisely built up section by section — the right choice depends on matching the warping method''s strengths to the specific fabric design''s complexity.', 3, '{"warping"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Why must warp tension be kept highly uniform across ALL ends on a beam (not just consistent on average) during weaving?', '["Uniformity has no practical effect on weaving outcomes","Ends under lower relative tension will be less taut in the shed, producing a fabric surface irregularity and increasing that specific end''s risk of forming defects like loose picks or uneven fell lines, even if the AVERAGE tension across the beam looks acceptable","Only the total tension sum matters, not distribution","Warp tension is automatically uniform on every loom by mechanical default"]'::jsonb, 'Ends under lower relative tension will be less taut in the shed, producing a fabric surface irregularity and increasing that specific end''s risk of forming defects like loose picks or uneven fell lines, even if the AVERAGE tension across the beam looks acceptable', 'Even if the average tension across a warp beam is within spec, individual low-tension ends behave differently in the shed (less taut, potentially causing localized fabric irregularity or preferential breakage at that position) — this is why tension UNIFORMITY across all ends, not just average tension, is monitored and controlled in quality warping and weaving preparation.', 3, '{"warp-tension"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Comparing shuttle looms to shuttleless (rapier/air-jet/projectile) looms broadly, the historical shift away from shuttle weaving in most modern mills happened primarily because shuttleless technology offers:', '["Identical speed and noise levels, so there was no real reason to switch","Significantly higher production speed, lower noise, and typically better fabric quality/consistency, despite shuttle looms still having a narrow niche in producing genuine woven selvedge for premium/heritage denim","Only lower cost machines with no performance benefit","The ability to weave without any weft yarn at all"]'::jsonb, 'Significantly higher production speed, lower noise, and typically better fabric quality/consistency, despite shuttle looms still having a narrow niche in producing genuine woven selvedge for premium/heritage denim', 'Shuttleless technologies (rapier, air-jet, projectile) dramatically outperform traditional flying-shuttle looms in speed and noise, which drove the industry-wide shift — but shuttle looms persist in a real niche because their continuous single-weft-thread selvedge construction produces the authentic ''selvedge denim'' edge that heritage/premium denim brands specifically market as a quality/authenticity feature.', 2, '{"shuttle-vs-shuttleless"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A weaving mill switching a style from air-jet to rapier looms (same fabric design) would most likely make this change if the new order required:', '["A simple, single-color, high-volume run with no special requirements","Multi-colored weft patterns (e.g., stripes) requiring frequent, precise weft color changes, which rapier systems handle more readily via multiple weft color selection than typical air-jet setups","Only pure white fabric with no color variation","A fabric that uses no weft yarn whatsoever"]'::jsonb, 'Multi-colored weft patterns (e.g., stripes) requiring frequent, precise weft color changes, which rapier systems handle more readily via multiple weft color selection than typical air-jet setups', 'While air-jet excels at high-speed single/limited-color production, rapier looms are traditionally favored for fabrics requiring flexible, frequent multi-color weft selection (like woven stripes and checks), since their positive gripper mechanism handles weft color-changing more straightforwardly — a key practical reason for choosing rapier over air-jet for certain designs.', 3, '{"loom-selection","multi-color"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Healds (heddles) can be made of flat steel wire or cord/twine. For high-speed synthetic filament weaving, wire healds are generally preferred mainly because they:', '["Are always cheaper regardless of application","Offer a smoother, more precise, low-friction eye surface with better durability at high speed, reducing yarn abrasion and heald wear compared to cord healds","Cannot be used with any natural fiber","Eliminate the need for any shedding motion"]'::jsonb, 'Offer a smoother, more precise, low-friction eye surface with better durability at high speed, reducing yarn abrasion and heald wear compared to cord healds', 'Flat steel healds provide a smooth, dimensionally precise eye that causes less yarn friction/abrasion at high shedding frequency and lasts longer under continuous high-speed cycling — cord healds are cheaper and still used in some applications but wear faster and are less precise at high speeds.', 2, '{"healds"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', '''Negative let-off'' systems control warp beam unwinding using a braking/friction mechanism responding to warp tension, while ''positive let-off'' systems mechanically drive the beam at a precisely calculated speed. Positive let-off is generally preferred for:', '["Any application, since it has zero disadvantages","Fabrics requiring very precise, consistent warp tension throughout the entire beam (from full to nearly empty), since tension doesn''t drift as beam diameter decreases, unlike simple negative systems","Only very cheap, low-quality fabric production","Situations where warp tension control doesn''t matter at all"]'::jsonb, 'Fabrics requiring very precise, consistent warp tension throughout the entire beam (from full to nearly empty), since tension doesn''t drift as beam diameter decreases, unlike simple negative systems', 'As a warp beam unwinds, its diameter shrinks; simple negative (friction-brake) let-off can let effective tension drift as this diameter changes, while a positive, electronically-controlled let-off precisely calculates and drives the correct unwind rate throughout the whole beam''s life, giving more consistent tension — valuable for quality-critical or beam-full-to-empty consistency-sensitive fabrics.', 3, '{"let-off-systems"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A weaving mill notices that fabric quality (evenness of PPI) is noticeably worse near the END of each warp beam (when the beam diameter is small) compared to the beginning. With a simple negative (friction-brake) let-off system, the most likely explanation is:', '["Beam diameter has no relationship to let-off tension control","As beam diameter decreases, a fixed braking force produces a different effective unwind tension than it did at full diameter, since the torque-to-tension relationship changes with radius — causing tension (and therefore fabric quality) drift over the beam''s life","The weft yarn quality always degrades near the end of production for unrelated reasons","The loom automatically slows down near the end of every beam"]'::jsonb, 'As beam diameter decreases, a fixed braking force produces a different effective unwind tension than it did at full diameter, since the torque-to-tension relationship changes with radius — causing tension (and therefore fabric quality) drift over the beam''s life', 'For a friction-brake (negative) let-off, the relationship between the fixed braking torque and the resulting warp tension depends on the beam''s current radius (tension = torque/radius, roughly) — so as the beam empties and radius shrinks, effective tension can drift, explaining measurable fabric quality/PPI differences from beam-start to beam-end, a documented limitation motivating positive let-off systems.', 3, '{"let-off-systems","tension-drift"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Weft ''crimp'' (the wave-like path a weft thread follows as it interlaces over/under warp ends, rather than lying perfectly straight) directly affects:', '["Only the fabric''s color depth","The fabric''s final dimensions (length/width shrinkage potential), GSM, and hand-feel, since crimped yarn occupies more linear path length than the flat fabric distance it spans","Nothing measurable about the finished fabric","Only the loom''s weft insertion speed"]'::jsonb, 'The fabric''s final dimensions (length/width shrinkage potential), GSM, and hand-feel, since crimped yarn occupies more linear path length than the flat fabric distance it spans', 'Because interlacing forces yarn to bend up and down rather than travel in a straight line, the actual yarn LENGTH used is greater than the flat fabric distance it covers — this crimp percentage directly affects fabric weight (GSM), influences dimensional/shrinkage behavior, and contributes to hand-feel, making it a real, measurable fabric engineering parameter, not just a structural curiosity.', 3, '{"crimp"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A fabric engineer wants to increase a woven fabric''s GSM without changing yarn count. Increasing weft crimp (e.g., via looser warp tension or tighter weave) can help because higher crimp:', '["Automatically reduces the total yarn length used in the fabric","Means more actual yarn length (and thus more mass) is packed into the same flat fabric area/length, increasing GSM even at a constant yarn count and thread density on paper","Has no relation to fabric weight, only to color","Only works if the yarn count is also changed simultaneously"]'::jsonb, 'Means more actual yarn length (and thus more mass) is packed into the same flat fabric area/length, increasing GSM even at a constant yarn count and thread density on paper', 'Since crimped yarn covers more actual linear length than the flat fabric span, higher crimp packs more yarn mass into the same fabric footprint — this is a real, exploitable lever for adjusting fabric weight/hand independent of simply changing yarn count or nominal thread density.', 3, '{"crimp","GSM"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', '''Fabric bow'' and ''fabric skew'' are related but distinct weft-alignment defects. The key difference is:', '["They are identical defects with two different names","Bow is a curved (arc-shaped) distortion of the weft line across the fabric width, while skew is a straight-line diagonal misalignment of the weft relative to the warp — both cause garment panels cut from the fabric to twist or distort after washing","Bow only affects knit fabric, never woven fabric","Skew only happens during dyeing, never during weaving"]'::jsonb, 'Bow is a curved (arc-shaped) distortion of the weft line across the fabric width, while skew is a straight-line diagonal misalignment of the weft relative to the warp — both cause garment panels cut from the fabric to twist or distort after washing', 'Both defects mean the weft isn''t perfectly perpendicular to the warp, but their geometry differs: bow curves (often from uneven tentering/finishing tension across the fabric width), while skew is a consistent diagonal shift — both are serious defects because garments cut from bowed/skewed fabric can visibly twist or lean after the customer''s first wash.', 3, '{"fabric-bow","fabric-skew"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A ''4-point fabric inspection system'' used in grey/finished fabric QC assigns penalty points based on:', '["The fabric''s color only, ignoring any physical defects","The length and severity of each defect found, with a maximum of 4 penalty points per single defect regardless of how severe, then totaled and compared to an allowable points-per-100-square-yards limit for pass/fail grading","Random sampling with no defined scoring rule","Only defects visible from more than 10 meters away"]'::jsonb, 'The length and severity of each defect found, with a maximum of 4 penalty points per single defect regardless of how severe, then totaled and compared to an allowable points-per-100-square-yards limit for pass/fail grading', 'The 4-point system is a standardized fabric grading method: defects are scored 1-4 points based on their length/severity (capped at 4 points even for very long defects), points are summed per 100 square yards inspected, and the fabric is accepted/rejected based on whether total points stay under an agreed threshold — a widely used objective fabric QC standard.', 2, '{"4-point-inspection"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', '''Weft bareness'' or ''weft bar'' (a visible horizontal line/band defect running across the full fabric width) is typically caused by:', '["A single isolated broken warp end","A change in weft yarn characteristics (e.g., different lot/count/twist/tension) at that specific pick range, or a period of incorrect PPI/beating settings, creating a visible density or shade band across the full width","The fabric being folded incorrectly after weaving","Correct, consistent weft supply with no yarn change"]'::jsonb, 'A change in weft yarn characteristics (e.g., different lot/count/twist/tension) at that specific pick range, or a period of incorrect PPI/beating settings, creating a visible density or shade band across the full width', 'Because weft bar/bareness runs the full width of the fabric (unlike a lengthwise warp-direction defect), it points to something affecting an entire pick-range uniformly — most commonly a weft package/lot change with slightly different properties, or a period of altered machine settings (tension, PPI) — rather than an isolated single-end problem.', 3, '{"weft-bar","defects"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Balanced fabric construction (roughly equal warp and weft thread density and yarn count, e.g., similar EPI and PPI) is often specified for shirting because it generally gives:', '["No practical benefit over an unbalanced construction","More uniform strength, drape, and dimensional stability in both the warp and weft directions, avoiding a fabric that is noticeably stronger/stiffer in one direction than the other","Automatically the lowest possible fabric cost regardless of design","Only a cosmetic, non-functional difference"]'::jsonb, 'More uniform strength, drape, and dimensional stability in both the warp and weft directions, avoiding a fabric that is noticeably stronger/stiffer in one direction than the other', 'A balanced construction (similar EPI/PPI and yarn count in both directions) avoids the pronounced directional differences in strength, stretch, and drape that an unbalanced fabric (e.g., much higher EPI than PPI) would show — for general-purpose shirting where consistent handle and behavior in all directions matters, balance is a deliberate design choice.', 2, '{"balanced-construction"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Why do wider weaving machines (e.g., 3.6m sectional warp looms for bedsheets) typically run at somewhat LOWER maximum RPM than narrower looms (e.g., 1.9m shirting looms) of similar technology generation?', '["Wider looms always run faster because they have bigger motors","The reed/sley mechanism must travel a much larger distance and accelerate/decelerate a heavier moving mass on a wider loom within the same cycle time, creating greater mechanical stress that limits achievable RPM without excessive wear/vibration","Loom width has no relationship to achievable speed","Wider looms use a completely different, unrelated weft insertion principle"]'::jsonb, 'The reed/sley mechanism must travel a much larger distance and accelerate/decelerate a heavier moving mass on a wider loom within the same cycle time, creating greater mechanical stress that limits achievable RPM without excessive wear/vibration', 'The beating mechanism (reed/sley) must fully oscillate across the entire loom width for every single pick; a wider loom means more mass moving a longer distance within the same fraction of a second at high RPM, creating proportionally greater mechanical stress/vibration — this physical constraint is why wider looms generally have lower maximum speed ratings than narrower ones of comparable technology.', 3, '{"loom-width","speed-tradeoff"}'::text[]);
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Multiple shuttle box mechanisms (an older technology allowing a shuttle loom to weave with several different weft colors by selecting different shuttles) were largely made obsolete for new installations by:', '["A complete ban on multi-color woven fabric","Modern shuttleless (rapier/projectile) multi-color weft selection systems, which achieve the same multi-color capability at much higher speed and lower noise/maintenance than mechanically complex multiple shuttle box systems","The invention of dyeing, which replaced the need for colored weft entirely","Multiple shuttle boxes are actually still the fastest method available today"]'::jsonb, 'Modern shuttleless (rapier/projectile) multi-color weft selection systems, which achieve the same multi-color capability at much higher speed and lower noise/maintenance than mechanically complex multiple shuttle box systems', 'Multiple shuttle box mechanisms solved the same problem (weaving with several weft colors) that modern rapier/projectile weft color selectors solve, but the mechanically complex, heavy shuttle-box-changing mechanism was inherently slower and noisier than modern shuttleless multi-color feed systems, driving its obsolescence for new mill installations.', 3, '{"multiple-shuttle-box","history"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', '''Grey fabric'' (also spelled ''greige'') refers to:', '["Fabric that has been dyed a grey color","Fabric straight off the loom, before any wet processing (desizing, scouring, bleaching, dyeing, or finishing) has been applied","A defect classification for fabric with reed marks","Fabric made only from grey-colored yarn"]'::jsonb, 'Fabric straight off the loom, before any wet processing (desizing, scouring, bleaching, dyeing, or finishing) has been applied', '''Grey'' or ''greige'' is industry terminology for unprocessed loom-state fabric (still containing size, natural impurities, and no dye/finish) — it has nothing to do with the color grey; it''s simply the fabric''s state prior to entering the wet processing/finishing pipeline.', 1, '{"grey-fabric"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A weaving mill inspects grey fabric before shipping it to a dye house, even though many visual defects (like slight soiling) will be removed by scouring/bleaching anyway. Why inspect at the grey stage rather than skip straight to inspecting after finishing?', '["Grey-stage inspection is pointless and mills never actually do this","Catching structural weaving defects (reed marks, floats, missing picks, bow/skew potential) at the grey stage allows correction or rejection before investing further dyeing/finishing cost into fabric that already has an unfixable structural flaw","Grey fabric defects always disappear completely during dyeing regardless of severity","Grey inspection only checks color, which is why it''s done early"]'::jsonb, 'Catching structural weaving defects (reed marks, floats, missing picks, bow/skew potential) at the grey stage allows correction or rejection before investing further dyeing/finishing cost into fabric that already has an unfixable structural flaw', 'While cosmetic soiling washes out, STRUCTURAL weaving defects (a genuine missing pick, a float, reed marks from mis-denting) are permanent and unaffected by later wet processing — catching these early avoids wasting dyeing/finishing costs (chemicals, energy, time) on fabric that will ultimately be rejected anyway for a defect wet processing cannot fix.', 3, '{"grey-inspection","QC"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Sizing ingredients commonly include starch (natural) and PVA/acrylic-based synthetic sizes. A mill weaving polyester or poly-blend warp yarn would generally prefer:', '["Only natural starch, since it works equally well on all fiber types","A synthetic size (like PVA) with better film-forming and adhesion compatibility on smooth, hydrophobic synthetic fiber surfaces, since natural starch adheres less effectively to non-cellulosic fibers","No sizing at all, since synthetic fiber never needs any size","A size chosen at random, since fiber type doesn''t affect size selection"]'::jsonb, 'A synthetic size (like PVA) with better film-forming and adhesion compatibility on smooth, hydrophobic synthetic fiber surfaces, since natural starch adheres less effectively to non-cellulosic fibers', 'Starch''s adhesion chemistry is well-matched to cellulose fiber but adheres less effectively to smooth, hydrophobic synthetic fiber surfaces; synthetic sizing agents like PVA or acrylics are formulated with better film-forming and adhesion properties on polyester/synthetic yarn, which is why size selection is matched to the specific warp fiber type being processed.', 3, '{"sizing","fiber-compatibility"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', '''Early shedding'' vs ''late shedding'' timing (the phase relationship between when the shed fully opens relative to when the weft insertion element enters) is a critical loom setting because:', '["Timing has no effect on weaving performance","If the shed isn''t sufficiently open at the moment of weft insertion, the inserting element (rapier tip, air jet, shuttle, or projectile) can strike/damage warp yarns, causing breaks, while shedding too early unnecessarily strains the warp with extended open-shed time","Shed timing only matters for jacquard looms, not other shedding types","Early and late shedding always produce identical fabric with no operational difference"]'::jsonb, 'If the shed isn''t sufficiently open at the moment of weft insertion, the inserting element (rapier tip, air jet, shuttle, or projectile) can strike/damage warp yarns, causing breaks, while shedding too early unnecessarily strains the warp with extended open-shed time', 'Precise timing between the shedding motion and weft insertion is critical: insufficient shed opening at the insertion moment causes the weft-carrying element to physically strike and damage warp ends (breakage risk), while excessively early/prolonged shed opening keeps warp under maximum strain longer than necessary — loom timing diagrams are carefully engineered to balance this.', 3, '{"shed-timing"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A weft straightener (used in some finishing lines, related to correcting bow/skew) works by:', '["Physically re-weaving the fabric with a different weft angle","Using rollers or a mechanical/optical feedback system to detect the actual weft line angle and then differentially stretch/adjust sections of the fabric width to realign the weft closer to perpendicular before further finishing","Bleaching the fabric to hide the defect visually only","Adding new weft yarn to replace the misaligned picks"]'::jsonb, 'Using rollers or a mechanical/optical feedback system to detect the actual weft line angle and then differentially stretch/adjust sections of the fabric width to realign the weft closer to perpendicular before further finishing', 'Weft straighteners use sensors to detect the actual weft path across the fabric width, then apply differential tension/stretch via curved or independently-controlled rollers to physically pull the fabric back toward a straighter, more perpendicular weft alignment before it proceeds to further finishing — a corrective step for bow/skew rather than a re-weaving process.', 3, '{"weft-straightener"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Needle looms (used for narrow fabric like tapes, webbing, and ribbons) differ from standard broad-woven looms mainly in that they:', '["Cannot use any weft insertion mechanism at all","Use a needle mechanism (rather than shuttle/rapier/jet) to carry weft through a narrow, typically leno-edge-secured fabric width, suited to producing many narrow strips simultaneously side by side","Only produce fabric wider than 2 meters","Require no warp yarn, only weft"]'::jsonb, 'Use a needle mechanism (rather than shuttle/rapier/jet) to carry weft through a narrow, typically leno-edge-secured fabric width, suited to producing many narrow strips simultaneously side by side', 'Needle looms are purpose-built for narrow fabric (tapes, labels, webbing, ribbons), using a needle-based weft insertion method adapted to weaving many narrow widths in parallel on one machine, with leno or similar edge-locking to secure each narrow strip''s selvedge — a specialized niche distinct from broad fabric weaving technology.', 2, '{"needle-loom","narrow-fabric"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A mill''s fabric inspection finds a specific defect: single, short, dark oily-looking spots recurring at roughly the same position across multiple different fabric rolls. What should be investigated first?', '["The dye recipe used at the dye house, since it is unrelated to weaving","A specific mechanical component on the loom (e.g., an over-lubricated moving part dripping oil onto the fabric at a consistent position) since the defect recurs at a consistent position across MULTIPLE rolls, pointing to a fixed machine-location cause rather than a random material issue","The warp beam''s total yardage, unrelated to the defect''s appearance","The finished fabric''s GSM specification"]'::jsonb, 'A specific mechanical component on the loom (e.g., an over-lubricated moving part dripping oil onto the fabric at a consistent position) since the defect recurs at a consistent position across MULTIPLE rolls, pointing to a fixed machine-location cause rather than a random material issue', 'A defect recurring at a consistent POSITION (not just a consistent interval) across multiple different fabric rolls strongly implicates a fixed physical cause at that location on the loom itself — such as a specific over-lubricated bearing or guide dripping oil onto the fabric at the same cross-width point every time — rather than a raw material or downstream process issue.', 3, '{"troubleshooting","oil-stain"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'Loom RPM and PPI (target pick density) together determine a loom''s linear fabric production rate. If a mill increases target PPI (denser fabric) while keeping loom RPM constant, what happens to the fabric''s linear production speed (meters/hour)?', '["Linear production speed increases","Linear production speed decreases, since each additional pick per inch means MORE total picks (and thus more loom cycles) are needed to produce the same length of fabric","Linear production speed is completely unaffected by PPI","PPI has no mathematical relationship to loom RPM or output"]'::jsonb, 'Linear production speed decreases, since each additional pick per inch means MORE total picks (and thus more loom cycles) are needed to produce the same length of fabric', 'Fabric linear output rate is inversely proportional to PPI at a fixed loom RPM (cycles/picks per minute) — denser fabric (higher PPI) requires more individual loom cycles to advance the same fabric length, directly slowing the rate of linear meters produced per hour even though the machine''s RPM hasn''t changed.', 3, '{"production-calc","PPI"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Two fabric styles use the exact same warp and weft yarn count and the same weave structure, but Style A has PPI=60 and Style B has PPI=40 (both otherwise identical). Style A will generally have:', '["Lower GSM (lighter fabric) than Style B","Higher GSM (heavier fabric) than Style B, since more weft yarn mass is packed into the same fabric area at higher pick density","Identical GSM to Style B, since GSM only depends on yarn count","GSM is unrelated to PPI in any weave"]'::jsonb, 'Higher GSM (heavier fabric) than Style B, since more weft yarn mass is packed into the same fabric area at higher pick density', 'GSM is directly influenced by thread density (EPI/PPI) at a given yarn count — more picks per inch means more total weft yarn mass packed into the same fabric area, so Style A (PPI=60) will weigh measurably more per square meter than Style B (PPI=40) with everything else held equal.', 2, '{"PPI","GSM"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'advanced', 'multiple_choice', 'A denim mill wants genuine ''selvedge denim'' (a self-finished, tightly woven edge characteristic of vintage-style shuttle-loom denim) for a premium product line. What is the technical reason this specifically requires shuttle looms rather than modern shuttleless looms?', '["Shuttleless looms cannot weave denim fabric at all","A shuttle carries a single continuous weft thread back and forth, naturally creating a tightly looped, self-finished edge at both selvedges with no cut ends, whereas shuttleless looms cut the weft at each edge and require a separate leno/tuck-in mechanism that doesn''t replicate the same continuous-loop selvedge look","Selvedge denim has nothing to do with the weaving method used","Modern looms are incapable of weaving any width narrower than 3 meters"]'::jsonb, 'A shuttle carries a single continuous weft thread back and forth, naturally creating a tightly looped, self-finished edge at both selvedges with no cut ends, whereas shuttleless looms cut the weft at each edge and require a separate leno/tuck-in mechanism that doesn''t replicate the same continuous-loop selvedge look', 'The defining feature of genuine selvedge denim is the continuous, unbroken weft loop at the fabric edge, a direct byproduct of the shuttle''s back-and-forth continuous-thread weaving action — shuttleless looms, which cut and individually secure each weft pick at the edges, cannot replicate this exact same continuous-loop selvedge structure, which is precisely why shuttle looms retain a premium/heritage niche for this specific product.', 3, '{"selvedge-denim","shuttle-loom"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Which combination of factors would most directly cause a weaving mill''s overall fabric output (in meters/day) to DROP even though loom RPM settings were never changed?', '["Increased warp/weft breakage rate (more stoppages) and/or increased target PPI (denser fabric requiring more picks per meter)","A decrease in the price of raw cotton","An increase in the number of workers in the finishing department","A change in the fabric''s approved color shade"]'::jsonb, 'Increased warp/weft breakage rate (more stoppages) and/or increased target PPI (denser fabric requiring more picks per meter)', 'With RPM held constant, actual linear output is governed by loom efficiency (breakage-driven downtime, directly cutting effective running time) and PPI (density, which sets how many loom cycles are needed per meter of fabric) — raw material pricing, downstream department staffing, and dye shade have no direct mechanical effect on the weaving stage''s meters/day output.', 2, '{"production-drop","root-cause"}'::text[]);
